-- Core tables every app built from this template has: people and roles, comments, activity,
-- attachments, automation runs and sync runs. RLS is on for every table.
-- Business tables come from app.schema.json (see 0002_*.sql, generated by `npm run schema:sql`).
-- Append-only: never edit this file after it is applied. Add a new migration instead.

create extension if not exists pgcrypto;

-- People and roles ---------------------------------------------------------------------------

create table public.app_roles (
  key text primary key,
  label text not null,
  can_read text[] not null default '{}',   -- table keys, or '*' for all
  can_write text[] not null default '{}'
);

insert into public.app_roles (key, label, can_read, can_write) values
  ('admin', 'Admin', array['*'], array['*']),
  ('pending', 'No access yet', array[]::text[], array[]::text[])
on conflict (key) do nothing;

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text not null,
  full_name text,
  role text not null default 'pending' references public.app_roles(key),
  active boolean not null default true,
  airtable_user_id text unique,           -- maps Airtable collaborators, createdBy and user fields
  created_at timestamptz not null default now()
);

-- Every new auth user gets a profile with no access. An admin sets the role (roles-and-access skill).
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, full_name)
  values (new.id, coalesce(new.email, ''), new.raw_user_meta_data->>'full_name')
  on conflict (id) do nothing;
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

create or replace function public.app_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and active
$$;

-- True when the current user's role may read/write the given table key.
create or replace function public.app_can(tbl text, action text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.profiles p join public.app_roles r on r.key = p.role
    where p.id = auth.uid() and p.active
      and (case when action = 'write' then r.can_write else r.can_read end) && array['*', tbl]
  )
$$;

-- Only admins change roles or deactivate people, even through the database API.
create or replace function public.guard_profile_update() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (new.role is distinct from old.role or new.active is distinct from old.active
      or new.email is distinct from old.email or new.airtable_user_id is distinct from old.airtable_user_id)
     and coalesce(public.app_role(), '') <> 'admin'
     and auth.uid() is not null then  -- service role, migrations and SQL editor have no auth.uid()
    raise exception 'Only an admin can change roles, access or email';
  end if;
  return new;
end $$;

create trigger profiles_guard before update on public.profiles
  for each row execute function public.guard_profile_update();

alter table public.app_roles enable row level security;
create policy app_roles_read on public.app_roles for select to authenticated using (true);

alter table public.profiles enable row level security;
create policy profiles_read on public.profiles for select to authenticated
  using (id = auth.uid() or public.app_role() is not null and public.app_role() <> 'pending');
create policy profiles_update_self on public.profiles for update to authenticated
  using (id = auth.uid() or public.app_role() = 'admin')
  with check (id = auth.uid() or public.app_role() = 'admin');

-- Shared helpers -------------------------------------------------------------------------------

create or replace function public.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

-- Comments, activity, attachments (one table each, for every business table) -------------------

create table public.comments (
  id uuid primary key default gen_random_uuid(),
  table_key text not null,
  record_id uuid not null,
  author_id uuid references public.profiles(id) on delete set null,
  author_name text,                       -- kept for comments imported from Airtable
  body text not null check (length(body) between 1 and 10000),
  airtable_id text unique,
  created_at timestamptz not null default now()
);
create index on public.comments (table_key, record_id, created_at);

alter table public.comments enable row level security;
create policy comments_read on public.comments for select to authenticated using (public.app_can(table_key, 'read'));
create policy comments_insert on public.comments for insert to authenticated
  with check (public.app_can(table_key, 'read') and author_id = auth.uid());
create policy comments_delete on public.comments for delete to authenticated
  using (author_id = auth.uid() or public.app_role() = 'admin');

create table public.activity (
  id bigint generated always as identity primary key,
  table_key text not null,
  record_id uuid not null,
  actor_id uuid references public.profiles(id) on delete set null,
  action text not null check (action in ('create', 'update', 'delete', 'import', 'sync', 'automation')),
  field text,
  old_value jsonb,
  new_value jsonb,
  created_at timestamptz not null default now()
);
create index on public.activity (table_key, record_id, created_at desc);

alter table public.activity enable row level security;
create policy activity_read on public.activity for select to authenticated using (public.app_can(table_key, 'read'));
create policy activity_insert on public.activity for insert to authenticated
  with check (public.app_can(table_key, 'write') and actor_id = auth.uid());

create table public.attachments (
  id uuid primary key default gen_random_uuid(),
  table_key text not null,
  record_id uuid not null,
  field text not null,
  path text not null unique,              -- object path in the "attachments" Storage bucket
  filename text not null,
  mime text,
  size bigint,
  airtable_id text unique,                -- attachment id from Airtable (att...)
  created_at timestamptz not null default now()
);
create index on public.attachments (table_key, record_id);

alter table public.attachments enable row level security;
create policy attachments_read on public.attachments for select to authenticated using (public.app_can(table_key, 'read'));
create policy attachments_write on public.attachments for insert to authenticated with check (public.app_can(table_key, 'write'));
create policy attachments_delete on public.attachments for delete to authenticated using (public.app_can(table_key, 'write'));

insert into storage.buckets (id, name, public) values ('attachments', 'attachments', false)
on conflict (id) do nothing;

-- Object paths are "<table_key>/<record_id>/<file>", so access follows the table.
create policy attachments_objects_read on storage.objects for select to authenticated
  using (bucket_id = 'attachments' and public.app_can(split_part(name, '/', 1), 'read'));
create policy attachments_objects_write on storage.objects for insert to authenticated
  with check (bucket_id = 'attachments' and public.app_can(split_part(name, '/', 1), 'write'));

-- Runs: automations and sync (written by the server with the service role; admins read) --------

create table public.automation_runs (
  id bigint generated always as identity primary key,
  automation text not null,
  status text not null default 'running' check (status in ('running', 'ok', 'error', 'skipped')),
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  items int not null default 0,
  detail jsonb,
  error text
);
create index on public.automation_runs (automation, started_at desc);

create table public.sync_runs (
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('copy', 'delta', 'final', 'parity')),
  table_key text,
  status text not null default 'running' check (status in ('running', 'ok', 'error')),
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  rows_read int not null default 0,
  rows_written int not null default 0,
  detail jsonb,
  error text
);
create index on public.sync_runs (started_at desc);

-- Last successful sync time per table, for the nightly delta.
create table public.sync_state (
  table_key text primary key,
  last_synced_at timestamptz not null
);

alter table public.automation_runs enable row level security;
alter table public.sync_runs enable row level security;
alter table public.sync_state enable row level security;
create policy automation_runs_read on public.automation_runs for select to authenticated using (public.app_role() = 'admin');
create policy sync_runs_read on public.sync_runs for select to authenticated using (public.app_role() = 'admin');
create policy sync_state_read on public.sync_state for select to authenticated using (public.app_role() = 'admin');
